public class Shop {
    static class Product {
        String name;
        double price;
        int stock;

        boolean sell(int qty) {
            if (qty > stock) return false;
            stock -= qty;
            return true;
        }

        @Override public String toString() { return name + " ($" + price + ", " + stock + " left)"; }
    }

    public static void main(String[] args) {
        Product p = new Product();
        p.name = "Mug"; p.price = 8.5; p.stock = 3;
        Product same = p;               // second reference to the same object
        same.sell(2);
        System.out.println(p);          // Mug ($8.5, 1 left)
