import java.util.List;

public class GenericsDemo {
    record Pair<A, B>(A first, B second) { }          // generic record

    static <T> T firstOrDefault(List<T> list, T fallback) {
        return list.isEmpty() ? fallback : list.get(0);
    }

    static <T extends Comparable<T>> T max(List<T> list) {
        T best = list.get(0);
        for (T item : list) if (item.compareTo(best) > 0) best = item;
        return best;
    }

    public static void main(String[] args) {
        var p = new Pair<>("age", 42);                // Pair<String, Integer>
        int age = p.second();                         // no cast needed
        System.out.println(p + " " + age);            // Pair[first=age, second=42] 42
        System.out.println(firstOrDefault(List.<String>of(), "none")); // none
        System.out.println(max(List.of(3, 9, 4)));    // 9
        System.out.println(max(List.of("pear", "apple"))); // pear
    }
}

import java.util.ArrayList;
