import java.util.List;

public class ListsDemo {
    record Person(String name, int age) { }

    public static void main(String[] args) {
        List<Person> people = new ArrayList<>(List.of(
                new Person("Cy", 41), new Person("Ana", 29), new Person("Bo", 29)));

        people.sort(Comparator.comparing(Person::age).thenComparing(Person::name));
        System.out.println(people.getFirst().name());    // Ana  (Java 21)
        people.removeIf(p -> p.age() > 40);
        System.out.println(people.size());               // 2

        List<Integer> nums = new ArrayList<>(List.of(5, 1, 7));
        nums.remove(1);                                  // removes index 1 -> [5, 7]
        nums.remove(Integer.valueOf(7));                 // removes value 7 -> [5]
        System.out.println(nums);                        // [5]

        List<String> fixed = List.of("x", "y");          // fixed.add("z") would throw
        System.out.println(fixed.reversed());            // [y, x]
    }
}

import java.util.*;

public class MapsSets {
    record Coord(int x, int y) { }                    // correct equals/hashCode for free

    public static void main(String[] args) {
        String text = "the cat and the hat and the bat";
        Map<String, Integer> counts = new TreeMap<>();
        for (String w : text.split(" ")) counts.merge(w, 1, Integer::sum);
        System.out.println(counts);   // {and=2, bat=1, cat=1, hat=1, the=3}

        Map<Integer, List<String>> byLength = new HashMap<>();
        for (String w : counts.keySet()) {
            byLength.computeIfAbsent(w.length(), k -> new ArrayList<>()).add(w);
        }
        System.out.println(byLength.get(3));          // [and, bat, cat, hat, the]

        Set<Coord> visited = new HashSet<>();
        visited.add(new Coord(1, 2));
        System.out.println(visited.add(new Coord(1, 2)));  // false: already present
        System.out.println(counts.getOrDefault("dog", 0)); // 0
    }
}

import java.util.List;
import java.util.function.*;

public class Lambdas {
    public static void main(String[] args) {
        Predicate<String> isBlank = String::isBlank;
        Predicate<String> hasContent = isBlank.negate();
        Function<String, Integer> length = String::length;
        Function<String, String> shout = s -> s.toUpperCase() + "!";
        Supplier<List<String>> names = () -> List.of("ana", " ", "bo");
        BinaryOperator<Integer> add = Integer::sum;

        int minLength = 2;                 // effectively final: captured below
        Predicate<String> longEnough = s -> s.length() >= minLength;

        for (String n : names.get()) {
            if (hasContent.and(longEnough).test(n)) {
                System.out.println(shout.andThen(length).apply(n) + " " + shout.apply(n));
            }
        }
        // 4 ANA!
        // 3 BO!
        System.out.println(add.apply(2, 3)); // 5
    }
}

